INSERT INTO blobs VALUES ('6e89980a71944734fa21661114cc24df1326e5625a50eb0da604fc67333d2105', '{"content":[{"result":{"mode":"single_tool","server":"telara","serverDescription":"Current date: 2026-07-29 (Wednesday) Current time (UTC): 2026-07-29T15:56:12Z Telara is a knowledge graph that has indexed your codebase across repositories, along with tickets, documents, messages, and logs from connected integrations. Every file, function, issue, and conversation is a node in a traversable graph — you can search semantically across all sources, follow relationships between code and tickets, trace function calls across repo boundaries, and read files from any indexed repository as if they were part of your local filesystem. YOUR INDEXED DATA SOURCES: Data sources are indexed into the knowledge graph. You can search their contents semantically, traverse relationships between them, and read their files directly. gitlab (all): all entities jira (all): all entities notion (all): all entities WHEN TO USE TELARA vs LOCAL TOOLS: Your local tools (grep, read, explore) see the current working directory. Telara sees everything above — every indexed repo, ticket, doc, and message — and the connections between them. - Editing or debugging a specific local file → local tools - Understanding how something works across services → telara_knowledge_search - Broad or cross-cutting questions (architecture, auth, billing, errors, \"what issues exist\") → telara_knowledge_search FIRST. These questions span multiple repos, tickets, and docs. Do not default to local grep for platform-wide questions. - Need to read a file from another repo → telara_archive_read (no cloning needed) - Check what depends on a file before changing it → telara_knowledge_impact - Trace a function''s callers/callees across repos → telara_code_call_hierarchy - Find related entities (tickets referencing a file, PRs touching a function) → telara_knowledge_traverse KNOWLEDGE TOOLS — Search and Explore the Graph: These tools work together as a pipeline. Start broad, then drill in: 1. telara_knowledge_search — Semantic search across ALL indexed sources (code, tickets, docs, messag…","serverStatus":"ready","tool":{"description":"Get detailed information about a specific issue including all fields, comments, and history. Pass fields=[attachments] to include any of these extras: attachments, changelog, comments, components, custom_fields, fix_versions, labels, subtasks. Returns: Single issue object: {id: string, key: \"PROJ-123\", summary: string, description: ADF object (structured content), status: {name, category}, priority: {name}, assignee: {display_name, email}|null, reporter: {display_name}, labels: [string], components: [{name}], fix_versions: [{name}], created: ISO 8601, updated: ISO 8601, resolution_date: ISO 8601|null, comments: [{author: {display_name}, body: ADF, created: ISO 8601}], history: [{author, created, items: [{field, from_string, to_string}]}].}","inputSchema":{"properties":{"cursor":{"description":"Opaque continuation token returned in _shaping.next_cursor by a previous truncated call. Pass back to fetch the next page.","type":"string"},"expand":{"description":"Comma-separated expand fields: changelog,renderedFields,transitions","type":"string"},"fields":{"description":"Optional comma-separated extras to include beyond the default projection. Available keys: attachments, changelog, comments, components, custom_fields, fix_versions, labels, subtasks. Example: fields=attachments.","type":"string"},"issue_key":{"description":"Issue key like ''PROJ-123''","format":"identifier","type":"string"},"max_items":{"description":"Max items returned in a list response. Defaults to 25. Pass `cursor` from the previous _shaping.next_cursor to continue.","type":"integer"},"mode":{"description":"Response shape: ''summary'' (concise, list-style) or ''detail'' (full payload). Defaults to summary for list_*/search_*/bulk_export_* actions, detail for get_*/create_*/update_*/delete_*.","enum":["summary","detail"],"type":"string"},"search_query":{"description":"Engine-side substring filter applied to list items across the tool''s search_fields (case-insensitive). Use when the upstream API lacks a query parameter.","type":"string"}},"required":["issue_key"],"type":"object"},"tool":"telara_jira_get_issue"}},"toolCallId":"call-69caabdc-058d-43df-995f-ddbee6c0f6d6-0\nfc_17ddbb15-22c7-905e-8178-f91772df9563_0","toolName":"GetMcpTools","type":"tool-result"}],"id":"call-69caabdc-058d-43df-995f-ddbee6c0f6d6-0\nfc_17ddbb15-22c7-905e-8178-f91772df9563_0","role":"tool"}');
