INSERT INTO blobs VALUES ('9800d94a606ff415ca5cf4c7bf4c01980ab0352a9781853855b913fb8d12f3c5', '{"content":[{"result":"package main\n\nimport (\n\t\"context\"\n\t\"net/http\"\n\t\"os\"\n\t\"strings\"\n\n\t\"github.com/gin-gonic/gin\"\n    10|\tagentProto \"gitlab.com/telara-labs/telara-proto/protos-go/agents/agent_service\"\n\tauthProto \"gitlab.com/telara-labs/telara-proto/protos-go/middleware/auth\"\n\ttelara_grpc_utils \"gitlab.com/telara-labs/telara-utilities/go/grpc\"\n\tgologger \"gitlab.com/telara-labs/telara-utilities/go/logging\"\n)\n\n// CLIEndpoints handles HTTP endpoints for the Telara CLI.\ntype CLIEndpoints struct {\n\tgateway *GatewayServer\n\tlogger  *gologger.Logger\n    20|}\n\n// NewCLIEndpoints creates a new CLIEndpoints handler.\nfunc NewCLIEndpoints(gateway *GatewayServer) *CLIEndpoints {\n\treturn &CLIEndpoints{\n\t\tgateway: gateway,\n\t\tlogger:  gologger.New(\"cli-endpoints\"),\n\t}\n}\n\n    30|// RegisterCLIRoutes mounts all /v1/cli/ routes on the Gin router.\nfunc (ce *CLIEndpoints) RegisterCLIRoutes(router *gin.Engine) {\n\t// Public — token validated inside the handler (for CLI to check its own token)\n\tpublicCLI := router.Group(\"/v1/cli\")\n\t{\n\t\tpublicCLI.POST(\"/auth/validate\", ce.ValidateCLIToken)\n\t\t// Device flow — public endpoints (no auth required; device_code is the secret)\n\t\tpublicCLI.POST(\"/auth/device/code\", ce.InitiateDeviceFlow)\n\t\tpublicCLI.POST(\"/auth/device/token\", ce.PollDeviceToken)\n\t}\n    40|\n\t// CLI-token auth — for CLI tool operations (logout + config/key management)\n\tcliAuthed := router.Group(\"/v1/cli\")\n\tcliAuthed.Use(ce.RequireCLITokenAuth())\n\t{\n\t\tcliAuthed.DELETE(\"/auth/token\", ce.RevokeCurrentToken)\n\t\tcliAuthed.GET(\"/configs/resolve\", ce.ResolveConfigs)\n\t\tcliAuthed.GET(\"/configs\", ce.ListConfigs)\n\t\tcliAuthed.GET(\"/configs/:id\", ce.GetConfig)\n\t\tcliAuthed.GET(\"/configs/:id/deployments\", ce.ListConfigDeployments)\n    50|\t\tcliAuthed.POST(\"/configs/:id/keys\", ce.GenerateKey)\n\t\tcliAuthed.GET(\"/configs/:id/keys\", ce.ListKeys)\n\t}\n\n\t// JWT auth — for dashboard PAT management UI and device flow verification\n\tdashboardCLI := router.Group(\"/v1/cli\")\n\tdashboardCLI.Use(ce.RequireJWTAuth())\n\t{\n\t\tdashboardCLI…","toolCallId":"call-69caabdc-058d-43df-995f-ddbee6c0f6d6-2\nfc_17ddbb15-22c7-905e-8178-f91772df9563_2","toolName":"Read","type":"tool-result"}],"id":"call-69caabdc-058d-43df-995f-ddbee6c0f6d6-2\nfc_17ddbb15-22c7-905e-8178-f91772df9563_2","role":"tool"}');
