INSERT INTO blobs VALUES ('f075bd889ce0f1a89370edbf64a6a098667d096fe9e42a21e266bedf08562b95', '{"content":[{"result":"<workspace_result workspace_path=\"/home/user/Desktop/Projects/Telara\">\ntelara-middleware/services/Gateway/src/cli_endpoints.go\n  574:func (ce *CLIEndpoints) GenerateKey(c *gin.Context) {\n  575-\tconfigID := c.Param(\"id\")\n  576-\tif configID == \"\" {\n  577-\t\tc.JSON(http.StatusBadRequest, gin.H{\"error\": \"config id is required\"})\n  578-\t\treturn\n  579-\t}\n  580-\n  581-\tvar body struct {\n  582-\t\tName             string `json:\"name\" binding:\"required\"`\n  583-\t\tScopeType        string `json:\"scope_type\"`\n  584-\t\tScopeId          string `json:\"scope_id\"`\n  585-\t\tExpiresInSeconds int64  `json:\"expires_in_seconds\"`\n  586-\t}\n  587-\tif err := c.ShouldBindJSON(&body); err != nil {\n  588-\t\tc.JSON(http.StatusBadRequest, gin.H{\"error\": \"name is required\"})\n  589-\t\treturn\n  590-\t}\n  591-\n  592-\tjwtToken, _ := c.Get(\"cli_jwt_token\")\n  593-\tagentCtx := telara_grpc_utils.PropagateAuthContextWithToken(c.Request.Context(), jwtToken.(string))\n  594-\n  595-\tresp, err := ce.gateway.agentClient.GenerateMCPApiKey(agentCtx, &agentProto.GenerateMCPApiKeyRequest{\n  596-\t\tMcpConfigId:      configID,\n  597-\t\tName:             body.Name,\n  598-\t\tScopeType:        body.ScopeType,\n  599-\t\tScopeId:          body.ScopeId,\n  600-\t\tExpiresInSeconds: body.ExpiresInSeconds,\n  601-\t})\n  602-\tif err != nil {\n  603-\t\tce.logger.Error().Err(err).Str(\"config_id\", configID).Msg(\"failed to generate MCP API key\")\n  604-\t\tc.JSON(http.StatusInternalServerError, gin.H{\"error\": \"Failed to generate API key\"})\n  605-\t\treturn\n  606-\t}\n  607-\n  608-\tkey := resp.ApiKey\n  609-\tc.JSON(http.StatusCreated, gin.H{\n  610-\t\t\"id\":            key.Id,\n  611-\t\t\"mcp_config_id\": key.McpConfigId,\n  612-\t\t\"name\":          key.Name,\n  613-\t\t\"key_prefix\":    key.KeyPrefix,\n  614-\t\t\"scope_type\":    key.ScopeType,\n  615-\t\t\"scope_id\":      key.ScopeId,\n  616-\t\t\"created_at\":    key.CreatedAt,\n  617-\t\t\"expires_at\":    key.ExpiresAt,\n  618-\t\t\"raw_key\":       resp.RawKey,\n  619-\t\t\"mcp_url\":       resp.McpUrl,\n  620-\t\t\"warning\":       \"Store this key s…","toolCallId":"call-9e8f5dad-6487-42e1-8fa4-e579f37b67cb-9\nfc_2e9f9f80-c40d-924a-ada5-2e99c4a4d230_4","toolName":"Grep","type":"tool-result"}],"id":"call-9e8f5dad-6487-42e1-8fa4-e579f37b67cb-9\nfc_2e9f9f80-c40d-924a-ada5-2e99c4a4d230_4","role":"tool"}');
INSERT INTO blobs VALUES ('e7d24adcd50bd85f997b7c15e0a089cbbd73c7006b494a2bc3998ec03fda3c76', '{"content":[{"result":"package discovery\n\n// CredentialClass describes the presence and handling style of credentials\n// without retaining any credential value.\ntype CredentialClass string\n\nconst (\n\tCredentialInline        CredentialClass = \"CredentialInline\"\n\tCredentialEnvReferenced CredentialClass = \"CredentialEnvReferenced\"\n    10|\tCredentialOAuthManaged  CredentialClass = \"CredentialOAuthManaged\"\n\tCredentialNone          CredentialClass = \"CredentialNone\"\n\tCredentialUnknown       CredentialClass = \"CredentialUnknown\"\n)\n\n// ScanStatus describes the outcome of reading one client/scope config file.\ntype ScanStatus string\n\nconst (\n\tScanOK               ScanStatus = \"ScanOK\"\n    20|\tScanFileAbsent       ScanStatus = \"ScanFileAbsent\"\n\tScanParseFailed      ScanStatus = \"ScanParseFailed\"\n\tScanPermissionDenied ScanStatus = \"ScanPermissionDenied\"\n\tScanUnsupported      ScanStatus = \"ScanUnsupported\"\n)\n\nconst (\n\tTransportStdio   = \"stdio\"\n\tTransportHTTP    = \"http\"\n\tTransportSSE     = \"sse\"\n    30|\tTransportUnknown = \"unknown\"\n)\n\n// DiscoveredServer describes one MCP server entry found in one config file.\ntype DiscoveredServer struct {\n\tServerName      string          `json:\"serverName\"`\n\tTransport       string          `json:\"transport\"`\n\tEndpointHost    string          `json:\"endpointHost,omitempty\"`\n\tCommandIdentity string          `json:\"commandIdentity,omitempty\"`\n\tRawArgCount     int             `json:\"rawArgCount\"`\n    40|\tCredentialClass CredentialClass `json:\"credentialClass\"`\n\tCredentialHint  string          `json:\"credentialHint,omitempty\"`\n}\n\n// ConfigScanResult describes scanning one client family and scope pair.\ntype ConfigScanResult struct {\n\tClientFamily string             `json:\"clientFamily\"`\n\tScope        string             `json:\"scope\"`\n\tPathClass    string             `json:\"pathClass\"`\n\tServers      []DiscoveredServer `json:\"servers\"`\n    50|\tStatus       ScanStatus         `json:\"status\"`\n\tErrorClass   string             `json:\"errorClass,omitempty\"`\n}\n","toolCallId":"call-9e8f5dad-6487-42e1-8fa4-e579f37b67cb-10\nfc_2e9f9f80-c40d-924a-ada5-2e99c4a4d230_5","toolName":"Read","type":"tool-result"}],"id":"call-9e8f5dad-6487-42e1-8fa4-e579f37b67cb-10\nfc_2e9f9f80-c40d-924a-ada5-2e99c4a4d230_5","role":"tool"}');
INSERT INTO blobs VALUES ('0130e080eb1f4446da3e5d7746231f21ff710b164bd23bf39d75c355c6acb342', '{"content":[{"result":"package discovery\n\nimport (\n\t\"fmt\"\n\t\"sort\"\n\t\"time\"\n)\n\n// ReportSchemaVersion identifies the wire shape below. The gateway converts a\n    10|// report into the AIEstateDiscoveryReport protobuf; this package deliberately\n// does NOT depend on telara-proto so the CLI stays a small, dependency-light\n// binary that ships to employee machines.\nconst ReportSchemaVersion = \"ai-estate-discovery-report/v1\"\n\n// Credential class values on the wire. These mirror proto\n// AIEstateCredentialClass by name so the gateway conversion is a total mapping\n// with no defaulting. An unrecognised value must be rejected, never coerced to\n// NONE — \"unknown\" and \"absent\" are different facts.\nconst (\n    20|\tWireCredentialUnspecified   = \"AI_ESTATE_CREDENTIAL_CLASS_UNSPECIFIED\"\n\tWireCredentialNone          = \"AI_ESTATE_CREDENTIAL_CLASS_NONE\"\n\tWireCredentialInline        = \"AI_ESTATE_CREDENTIAL_CLASS_INLINE\"\n\tWireCredentialEnvReferenced = \"AI_ESTATE_CREDENTIAL_CLASS_ENV_REFERENCED\"\n\tWireCredentialOAuthManaged  = \"AI_ESTATE_CREDENTIAL_CLASS_OAUTH_MANAGED\"\n\tWireCredentialUnknown       = \"AI_ESTATE_CREDENTIAL_CLASS_UNKNOWN\"\n)\n\n// Collection status values, mirroring proto AIEstateCollectionStatus. Only\n// COMPLETE may ever license a tombstone downstream.\n    30|const (\n\tWireCollectionComplete = \"AI_ESTATE_COLLECTION_STATUS_COMPLETE\"\n\tWireCollectionPartial  = \"AI_ESTATE_COLLECTION_STATUS_PARTIAL\"\n\tWireCollectionFailed   = \"AI_ESTATE_COLLECTION_STATUS_FAILED\"\n)\n\n// CollectorIdentity describes the reporting collector. The gateway overrides\n// ReportedPrincipalID with the authenticated CLI token''s user; a collector\n// cannot assert evidence on behalf of someone else without explicit delegation.\ntype CollectorIdentity struct {\n    40|\tCollectorKind       string `json:\"collectorKind\"`\n\tCollectorVersion    string `json:\"collectorVersion\"`\n\tInstallationKey     string `json:\"installationKey\"`\n\tReportedPrincipalID string `json:\"reportedPrincipalId,omitempty\"`\n\tDeviceLabelClass    string `json:\"deviceLabelC…","toolCallId":"call-9e8f5dad-6487-42e1-8fa4-e579f37b67cb-11\nfc_2e9f9f80-c40d-924a-ada5-2e99c4a4d230_6","toolName":"Read","type":"tool-result"}],"id":"call-9e8f5dad-6487-42e1-8fa4-e579f37b67cb-11\nfc_2e9f9f80-c40d-924a-ada5-2e99c4a4d230_6","role":"tool"}');
INSERT INTO blobs VALUES ('a2827cd559858c95be1270a243922b957af88525234c45045b955a6054066b13', '{"content":[{"result":"<workspace_result workspace_path=\"/home/user/Desktop/Projects/Telara\">\ntelara-middleware/services/Gateway/src/gateway_passthrough.go\n  538:func (s *GatewayServer) ListAIEstateResources(ctx context.Context, req *knowledgepb.ListAIEstateResourcesRequest) (*knowledgepb.ListAIEstateResourcesResponse, error) {\n  539:\treturn s.knowledgeClient.KnowledgeServiceClient.ListAIEstateResources(ctx, req)\n  542:func (s *GatewayServer) GetAIEstateResource(ctx context.Context, req *knowledgepb.GetAIEstateResourceRequest) (*knowledgepb.GetAIEstateResourceResponse, error) {\n  543:\treturn s.knowledgeClient.KnowledgeServiceClient.GetAIEstateResource(ctx, req)\n  546:func (s *GatewayServer) ListAIEstateResourceRevisions(ctx context.Context, req *knowledgepb.ListAIEstateResourceRevisionsRequest) (*knowledgepb.ListAIEstateResourceRevisionsResponse, error) {\n  547:\treturn s.knowledgeClient.KnowledgeServiceClient.ListAIEstateResourceRevisions(ctx, req)\n  550:func (s *GatewayServer) ListAIEstateResourceRelationships(ctx context.Context, req *knowledgepb.ListAIEstateResourceRelationshipsRequest) (*knowledgepb.ListAIEstateResourceRelationshipsResponse, error) {\n  551:\treturn s.knowledgeClient.KnowledgeServiceClient.ListAIEstateResourceRelationships(ctx, req)\n  554:func (s *GatewayServer) ListAIEstateResourceObservations(ctx context.Context, req *knowledgepb.ListAIEstateResourceObservationsRequest) (*knowledgepb.ListAIEstateResourceObservationsResponse, error) {\n  555:\treturn s.knowledgeClient.KnowledgeServiceClient.ListAIEstateResourceObservations(ctx, req)\n\ntelara-middleware/services/Gateway/src/gateway_ai_estate_passthrough_test.go\n  23:func (s *estateReadRecorder) ListAIEstateResources(ctx context.Context, _ *knowledgepb.ListAIEstateResourcesRequest) (*knowledgepb.ListAIEstateResourcesResponse, error) {\n  25:\treturn &knowledgepb.ListAIEstateResourcesResponse{Resources: []*knowledgepb.AIEstateResource{{ResourceId: \"estate-resource\"}}}, nil\n  28:func TestListAIEstateResourcesForwardsAuthenticat…","toolCallId":"call-9e8f5dad-6487-42e1-8fa4-e579f37b67cb-12\nfc_2e9f9f80-c40d-924a-ada5-2e99c4a4d230_7","toolName":"Grep","type":"tool-result"}],"id":"call-9e8f5dad-6487-42e1-8fa4-e579f37b67cb-12\nfc_2e9f9f80-c40d-924a-ada5-2e99c4a4d230_7","role":"tool"}');
INSERT INTO blobs VALUES ('f08925429a5a77a6709568f89024990e8172e86e147a356cc91729f141defb01', '{"content":[{"result":"package cmd\n\nimport (\n\t\"context\"\n\t\"fmt\"\n\t\"os\"\n\n\t\"github.com/spf13/cobra\"\n\t\"gitlab.com/telara-labs/telara-cli/services/cli/internal/agent\"\n    10|\t\"gitlab.com/telara-labs/telara-cli/services/cli/internal/api\"\n\t\"gitlab.com/telara-labs/telara-cli/services/cli/internal/auth\"\n\t\"gitlab.com/telara-labs/telara-cli/services/cli/internal/display\"\n)\n\nvar whoamiCmd = &cobra.Command{\n\tUse:   \"whoami\",\n\tShort: \"Show who you are logged in as and which organization you belong to\",\n\tRunE: func(cmd *cobra.Command, args []string) error {\n\t\ttoken, err := auth.LoadToken(prefs.APIURL)\n    20|\t\tif err != nil {\n\t\t\treturn fmt.Errorf(\"not logged in — run: telara login --token <tlrc_...>\")\n\t\t}\n\n\t\tclient := api.NewClient(prefs.APIURL, token)\n\t\twhoami, err := client.ValidateToken(context.Background())\n\t\tif err != nil {\n\t\t\treturn fmt.Errorf(\"failed to verify <redacted assigned secret> telara login --token <tlrc_...>\", err)\n\t\t}\n\n    30|\t\tdisplay.PrintKV(os.Stdout, \"User:\", whoami.DisplayName)\n\t\tdisplay.PrintKV(os.Stdout, \"Email:\", whoami.Email)\n\t\tdisplay.PrintKV(os.Stdout, \"Organization:\", whoami.OrgName)\n\t\tdisplay.PrintKV(os.Stdout, \"Token prefix:\", whoami.TokenPrefix)\n\t\tif prefs.ActiveContext != \"\" {\n\t\t\tdisplay.PrintKV(os.Stdout, \"Global config:\", prefs.ActiveContext)\n\t\t}\n\t\twiredState, _ := agent.LoadWiredState()\n\t\tif wiredState != nil && wiredState.Projects != nil {\n\t\t\tif cwd, err := os.Getwd(); err == nil {\n    40|\t\t\t\tif wc, ok := wiredState.Projects[cwd]; ok && wc != nil {\n\t\t\t\t\tdisplay.PrintKV(os.Stdout, \"Project config:\", wc.ConfigName)\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn nil\n\t},\n}\n\nfunc init() {\n    50|\trootCmd.AddCommand(whoamiCmd)\n}\n","toolCallId":"call-9e8f5dad-6487-42e1-8fa4-e579f37b67cb-13\nfc_2e9f9f80-c40d-924a-ada5-2e