INSERT INTO blobs VALUES ('e8ed49d8bee20e733f69c657e7c1f98094397fae5d1adb81ce249a322534b29d', '{"content":[{"result":"package cmd\n\nimport (\n\t\"bufio\"\n\t\"context\"\n\t\"fmt\"\n\t\"os\"\n\t\"runtime\"\n\t\"strings\"\n    10|\n\t\"github.com/spf13/cobra\"\n\t\"gitlab.com/telara-labs/telara-cli/services/cli/internal/api\"\n\t\"gitlab.com/telara-labs/telara-cli/services/cli/internal/auth\"\n\t\"gitlab.com/telara-labs/telara-cli/services/cli/internal/clicontext\"\n\t\"gitlab.com/telara-labs/telara-cli/services/cli/internal/display\"\n)\n\nvar reportCmd = &cobra.Command{\n\tUse:   \"report\",\n    20|\tShort: \"Submit a bug report to the Telara team\",\n\tLong: `Submit a bug report directly from the CLI.\nIf authenticated, your user details are included automatically.\nOtherwise you will be prompted for your name and email.`,\n\tRunE: runReport,\n}\n\nfunc init() {\n\treportCmd.Flags().StringP(\"title\", \"t\", \"\", \"Bug title (required)\")\n\treportCmd.Flags().StringP(\"severity\", \"s\", \"medium\", \"Severity: low, medium, high, critical\")\n    30|\treportCmd.Flags().StringP(\"description\", \"d\", \"\", \"Bug description\")\n\trootCmd.AddCommand(reportCmd)\n}\n\nfunc runReport(cmd *cobra.Command, args []string) error {\n\ttitle, _ := cmd.Flags().GetString(\"title\")\n\tseverity, _ := cmd.Flags().GetString(\"severity\")\n\tdescription, _ := cmd.Flags().GetString(\"description\")\n\n\treader := bufio.NewReader(os.Stdin)\n    40|\n\tif title == \"\" {\n\t\tfmt.Fprint(os.Stderr, \"Bug title: \")\n\t\tline, _ := reader.ReadString(''\\n'')\n\t\ttitle = strings.TrimSpace(line)\n\t\tif title == \"\" {\n\t\t\treturn fmt.Errorf(\"title is required\")\n\t\t}\n\t}\n\n    50|\tif description == \"\" {\n\t\tfmt.Fprint(os.Stderr, \"Description: \")\n\t\tline, _ := reader.ReadString(''\\n'')\n\t\tdescription = strings.TrimSpace(line)\n\t\tif description == \"\" {\n\t\t\treturn fmt.Errorf(\"description is required\")\n\t\t}\n\t}\n\n\t// Build environment info\n    60|\tenvironment := map[string]string{\n\t\t\"os\":   runtime.GOOS,\n\t\t\"arch\": runtime.GOARCH,\n\t}\n\tctxName := clicontext.Resolve(rootContext, prefs.ActiveContext)\n\tif ctxName != \"\" {\n\t\tenvironment[\"context\"] = ctxName\n\t}\n\tenvironment[\"api_url\"] = prefs.APIURL\n\n    70|\t// Determine auth state\n\tvar (\n\t\treporterEmail string\n\t\tre…","toolCallId":"call-9e8f5dad-6487-42e1-8fa4-e579f37b67cb-14\nfc_2e9f9f80-c40d-924a-ada5-2e99c4a4d230_9","toolName":"Read","type":"tool-result"}],"id":"call-9e8f5dad-6487-42e1-8fa4-e579f37b67cb-14\nfc_2e9f9f80-c40d-924a-ada5-2e99c4a4d230_9","role":"tool"}');
INSERT INTO blobs VALUES ('252887360bff02978df7cb5ae4bcde6f3407704d23d6470351b268348527ee1b', '{"content":[{"result":"package api\n\nimport (\n\t\"bytes\"\n\t\"context\"\n\t\"crypto/tls\"\n\t\"crypto/x509\"\n\t\"encoding/json\"\n\t\"fmt\"\n    10|\t\"io\"\n\t\"net/http\"\n\t\"os\"\n\t\"time\"\n)\n\n// Client is an HTTP client for the Telara API.\ntype Client struct {\n\tBaseURL    string\n\tToken      string\n    20|\tHTTPClient *http.Client\n}\n\n// NewClient creates a new API client for the given base URL and bearer token.\n//\n// TLS behaviour (checked in order):\n//  1. TELARA_INSECURE=true  — skip verification entirely (escape hatch, not recommended)\n//  2. TELARA_CA_CERT_PATH   — load a custom CA bundle (local dev with self-signed cert)\n//  3. default               — system CA pool (works for Let''s Encrypt / public CAs)\nfunc NewClient(baseURL, token string) *Client {\n    30|\tvar transport http.RoundTripper = http.DefaultTransport\n\n\tif os.Getenv(\"TELARA_INSECURE\") == \"true\" {\n\t\ttransport = &http.Transport{\n\t\t\tTLSClientConfig: &tls.Config{InsecureSkipVerify: true}, //nolint:gosec\n\t\t}\n\t} else if caPath := os.Getenv(\"TELARA_CA_CERT_PATH\"); caPath != \"\" {\n\t\tcaPEM, err := os.ReadFile(caPath)\n\t\tif err != nil {\n\t\t\tfmt.Fprintf(os.Stderr, \"error: TELARA_CA_CERT_PATH: cannot read %s: %v\\n\", caPath, err)\n    40|\t\t\tos.Exit(1)\n\t\t}\n\t\tpool := x509.NewCertPool()\n\t\tif !pool.AppendCertsFromPEM(caPEM) {\n\t\t\tfmt.Fprintf(os.Stderr, \"error: TELARA_CA_CERT_PATH: no valid certs found in %s\\n\", caPath)\n\t\t\tos.Exit(1)\n\t\t}\n\t\ttransport = &http.Transport{\n\t\t\tTLSClientConfig: &tls.Config{RootCAs: pool},\n\t\t}\n    50|\t}\n\n\treturn &Client{\n\t\tBaseURL: baseURL,\n\t\tToken:   token,\n\t\tHTTPClient: &http.Client{\n\t\t\tTimeout:   15 * time.Second,\n\t\t\tTransport: transport,\n\t\t},\n\t}\n    60|}\n\n// APIError represents a non-2xx response from the Telara API.\ntype APIError struct {\n\tStatusCode int\n\tMessage    string\n\tBody       string // raw response body\n}\n\nfunc (e *APIError) Error() string {\n    70|\treturn fmt.Sprintf(\"API error %d: %s\", e.StatusCode, e.Message)\n}\n\n// Post performs a POST request to the given path with the given body, decoding\n// the response into out (if non-nil).…","toolCallId":"call-9e8f5dad-6487-42e1-8fa4-e579f37b67cb-15\nfc_2e9f9f80-c40d-924a-ada5-2e99c4a4d230_10","toolName":"Read","type":"tool-result"}],"id":"call-9e8f5dad-6487-42e1-8fa4-e579f37b67cb-15\nfc_2e9f9f80-c40d-924a-ada5-2e99c4a4d230_10","role":"tool"}');
